    /// </summary>
    [Chunk(0x03092000)]
    [ChunkGameVersion(GameVersion.TMT | GameVersion.MP4 | GameVersion.TM2020, 2, 2, 9)]
    public partial class Chunk03092000 : SkippableChunk<CGameCtnGhost>, IVersionable
    {
        public override uint Id => 0x03092000;
        public override GameVersion GameVersion => GameVersion.TMT | GameVersion.MP4 | GameVersion.TM2020;
        public int Version { get; set; }
        public int U01;
        public int[]? U02;

        public Chunk03092000() : this(GameVersion.Unspecified)
        {
        }

        public Chunk03092000(GameVersion gameVersion)
        {
            if (gameVersion == GameVersion.TMT || gameVersion == GameVersion.MP4)
            {
                Version = 2;
            }
            else if (gameVersion == GameVersion.TM2020)
            {
                Version = 9;
            }

            U01 = 2;
        }

        internal override void DeepCloneFields(Chunk clone, DeepCloneContext context)
        {
            base.DeepCloneFields(clone, context);
            ((Chunk03092000)clone).Version = context.Clone(this.Version)!;
            ((Chunk03092000)clone).U01 = context.Clone(this.U01)!;
            ((Chunk03092000)clone).U02 = context.CloneArray(this.U02)!;
        }

        public override void ReadWrite(CGameCtnGhost n, GbxReaderWriter rw)
        {
            rw.VersionInt32(this);
            if (Version > 9)
            {
                throw new global::GBX.NET.Exceptions.ChunkVersionNotSupportedException(Version);
            }

            if (Version >= 9)
            {
                rw.Int32(ref n.appearanceVersion);
            }

            rw.Ident(ref n.playerModel);
            rw.Vec3(ref n.lightTrailColor);
            rw.ListPackDesc(ref n.skinPackDescs!);
            rw.Boolean(ref n.hasBadges);

            if (n.HasBadges)
            {
                rw.ReadableWritable<SBadge>(ref n.badge, version: Version);
            }

            if (n.AppearanceVersion>= 1)
            {
                rw.String(ref n.skinCustomization);
            }

            rw.String(ref n.ghostNickname);
            rw.String(ref n.ghostAvatarName);

            if (Version >= 2)
            {
                rw.String(ref n.recordingContext);

                if (Version >= 4)
                {
                    rw.Int32(ref U01);

                    if (Version >= 5)
                    {
                        rw.NodeRef(ref n.recordDataRef);
                        rw.Array<int>(ref U02!);

                        if (Version >= 6)
                        {
                            rw.String(ref n.ghostTrigram);

                            if (Version >= 7)
                            {
                                rw.String(ref n.ghostCountryPath);

                                if (Version >= 8)
                                {
                                    rw.String(ref n.ghostClubTag);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

